from collections import Counter

def transform(grid):
    """
    ARC Task 383dbda3 Transformation Rule:

    1. Markers (1s) stay at their positions
    2. 2s expand:
       - Rows with markers: 2s expand to cols 0-15 (left to 0, keep 1-15)
       - Rows without markers: FULLY FILLED (all 20 cols = 2)
    3. Bottom rows (9+): checkerboard pattern [2,0,2,0,2,0,2,2,0...] in connected columns
    """
    H, W = len(grid), len(grid[0])

    # Find markers and pattern color
    vals = Counter(v for r in grid for v in r)
    marker_color = 1 if 1 in vals else None
    pattern_color = 2 if 2 in vals else None

    # Markers stay
    if marker_color:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == marker_color:
                    output[r][c] = marker_color

    # Find existing 2s (pattern region)
    pattern_cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == pattern_color]

    if pattern_cells:
        # Get 2s block bounds
        rows_2 = {r for r, c in pattern_cells}
        cols_2 = {c for r, c in pattern_cells}
        cmin, cmax = min(cols_2), max(cols_2)

        # Compute marker rows (rows with markers)
        marker_rows = {r for r, c in grid for c_row in range(W) if grid[r][c_row] == marker_color}

        # Process each 2s row
        for r in rows_2:
            has_marker = r in marker_rows
            if has_marker:
                # Partial: expand left to 0, keep 2s range
                for c in range(cmin, cmax + 2):  # expand one more right too
                    if grid[r][c] != marker_color:
                        output[r][c] = pattern_color
                # Keep markers
            else:
                # Fully filled!
                for c in range(W):
                    if grid[r][c] != marker_color:
                        output[r][c] = pattern_color

        # Now for bottom rows (beyond 2s rows)
        if pattern_cells:
            rmax = max(rows_2)
            # Get connected columns from markers
            marker_cols = sorted(set(c for r in range(H) for c in range(W) if grid[r][c] == marker_color))
            connected_cols = set()
            for mc in marker_cols:
                for dc in [-1, 0, 1]:
                    connected_cols.add(mc + dc)

            # Checkboard pattern in connected columns
            for r in range(rmax + 1, H):
                for c in connected_cols:
                    if 0 <= c < W and output[r][c] == 0:
                        if (r + c) % 3 == 1:
                            output[r][c] = pattern_color

    return output

